from __future__ import annotations

from pathlib import Path
from typing import Any

from menai import Menai, MenaiBytes, MenaiDict, MenaiString

from menai_benchmark import BenchmarkCase, BenchmarkSuite, Implementation

_SUITE_DIR = Path(__file__).resolve().parent
_FIXTURES_DIR = _SUITE_DIR / "fixtures"

# Fixtures are generated by generate_fixtures.py and committed so every run
# reads byte-identical inputs.
_FIXTURE_NAMES = [
    "greyscale-64x64.png",
    "greyscale-alpha-64x64.png",
    "palette-128x128.png",
    "truecolour-128x128.png",
    "truecolour-alpha-128x128.png",
    "truecolour-192x192.png",
]

_ITERATIONS = 5

_EXPR = '(let ((png (import "png_parser"))) ((dict-get png "parse") (dict-get inputs "input-data")))'


class Suite(BenchmarkSuite):
    """Benchmark suite for the Menai PNG parser."""

    name = "png_parser"
    description = "Parse non-interlaced 8-bit PNG files of various colour types and sizes."

    def cases(self) -> list[BenchmarkCase]:
        """Return one case per fixture file."""
        return [
            BenchmarkCase(
                name=name.removesuffix(".png"),
                input=_FIXTURES_DIR / name,
                iterations=_ITERATIONS,
            )
            for name in _FIXTURE_NAMES
        ]

    def implementation(self, menai: Menai) -> Implementation:
        """Return the Menai PNG parser implementation."""
        def prepare_menai(fixture_path: Path) -> Any:
            """Compile the parse expression with the fixture bytes bound (untimed)."""
            inputs = MenaiDict(((MenaiString("input-data"), MenaiBytes(fixture_path.read_bytes())),))
            return menai.compile(_EXPR, inject=("inputs", inputs))

        def run_menai(code: Any) -> Any:
            """Execute the pre-compiled bytecode (timed)."""
            return menai.vm.execute(code)

        return Implementation(run=run_menai, prepare=prepare_menai)
